'use client'

import * as React from 'react'
import { cn, switchThumbVariants, switchVariants } from "@/lib/utils"

const Switch = React.forwardRef<
  HTMLButtonElement,
  Omit<
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    'checked' | 'defaultChecked' | 'onChange' | 'value'
  > & {
    checked?: boolean
    defaultChecked?: boolean
    required?: boolean
    onCheckedChange?: (checked: boolean) => void
    value?: string
  }
>(
  (
    {
      className,
      checked: checkedProp,
      defaultChecked,
      required,
      onCheckedChange,
      value = 'on',
      disabled,
      ...props
    },
    ref
  ) => {
    const [checkedState, setCheckedState] = React.useState<boolean>(
      checkedProp ?? defaultChecked ?? false
    )

    // Sync controlled state
    React.useEffect(() => {
      if (checkedProp !== undefined) {
        setCheckedState(checkedProp)
      }
    }, [checkedProp])

    const isChecked = checkedProp !== undefined ? checkedProp : checkedState

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (disabled) return

      const nextChecked = !isChecked

      // Update local state if uncontrolled
      if (checkedProp === undefined) {
        setCheckedState(nextChecked)
      }

      onCheckedChange?.(nextChecked)
      props.onClick?.(e)
    }

    return (
      <button
        type="button"
        role="switch"
        aria-checked={isChecked}
        data-state={isChecked ? 'checked' : 'unchecked'}
        data-slot="switch"
        disabled={disabled}
        value={value}
        className={cn(switchVariants(), className)}
        ref={ref}
        onClick={handleClick}
        {...props}
      >
        <span
          data-slot="switch-thumb"
          data-state={isChecked ? 'checked' : 'unchecked'}
          className={cn(switchThumbVariants())}
        />
      </button>
    )
  }
)
Switch.displayName = 'Switch'

export { Switch }

import { computed } from "vue";
import { normalizeProps, useMachine } from "@zag-js/vue";
import { switchConnect, switchMachine } from "@/lib/utils";
import type { SwitchVueProps } from "@/lib/utils";

type SwitchEmits = {
    (event: "update:modelValue", value: boolean): void;
    (event: "change", value: boolean): void;
};

export function useSwitch(props: SwitchVueProps, emit: SwitchEmits) {
    const machineProps = computed(() => ({
        id: props.id,
        checked: props.modelValue ?? props.checked,
        defaultChecked:
            props.modelValue === undefined && props.checked === undefined
                ? props.defaultChecked
                : undefined,
        disabled: props.disabled,
        required: props.required,
        name: props.name,
        value: props.value ?? 'on',
        onCheckedChange(details: { checked: boolean }) {
            emit('update:modelValue', details.checked)
            emit('change', details.checked)
        },
    }));

    const service = useMachine(switchMachine, machineProps);
    const api = computed(() => switchConnect(service, normalizeProps));

    return api;
}

import type { SwitchProps } from "@/lib/utils"

import { switchThumbVariants, switchVariants } from '../utils'

const switchProps = {
  checked: { type: Boolean, value: false },
  defaultChecked: { type: Boolean, value: false },
  disabled: { type: Boolean, value: false },
  required: { type: Boolean, value: false },
  readOnly: { type: Boolean, value: false },
  invalid: { type: Boolean, value: false },
  name: { type: String, value: '' },
  form: { type: String, value: '' },
  value: { type: null, value: 'on' },
  label: { type: String, value: '' },
  id: { type: String, value: '' },
  extClass: { type: String, value: '' },
}

type SwitchWeappProps = SwitchProps & {
  extClass?: string
}

type SwitchPropDefinition = {
  type:
    | StringConstructor
    | BooleanConstructor
    | NumberConstructor
    | ArrayConstructor
    | ObjectConstructor
    | FunctionConstructor
    | null
  value?: string | boolean | number | number[]
}

const switchPropsWithTypes = switchProps satisfies Partial<
  Record<keyof SwitchWeappProps, SwitchPropDefinition>
>

Component({
  properties: switchPropsWithTypes,
  data: {
    className: '',
    thumbClassName: '',
  },
  lifetimes: {
    attached() {
      this.setData({
        className: switchVariants({ className: this.properties.extClass }),
        thumbClassName: switchThumbVariants(),
      })
    },
  },
  observers: {
    extClass: function (extClass) {
      this.setData({
        className: switchVariants({ className: extClass }),
        thumbClassName: switchThumbVariants(),
      })
    },
    checked: function (checked) {
      this.setData({ checked })
    },
    defaultChecked: function (val) {
      if (this.properties.checked === false && val) {
        this.setData({ checked: val })
      }
    },
  },
  methods: {
    handleTap() {
      if (this.properties.disabled || this.properties.readOnly) return
      const newValue = !this.properties.checked
      this.setData({ checked: newValue })
      this.triggerEvent('change', { value: newValue })
    },
  },
})
